mapper.select:
select 
from biz_promotion p

    p.del_flag = '0'

        and p.promotion_no = #{promotionNo}


        and p.promotion_name like concat('%', #{promotionName}, '%')


        and p.promotion_type = #{promotionType}


        and p.scope_type = #{scopeType}


        and p.status = #{status}


        and p.is_special_price = #{isSpecialPrice}


        and p.create_time >= #{params.beginTime}


        and p.create_time <= #{params.endTime}


order by p.priority desc, p.promotion_id desc
